* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    background-color: #f5f5f5;
    color: #333;
}

.container {
    max-width: 1600px;
    margin: 0 auto;
    padding: 20px;
}

h1 {
    text-align: center;
    margin-bottom: 30px;
    font-size: 28px;
    color: #222;
}

h2 {
    font-size: 18px;
    margin-bottom: 15px;
    color: #444;
}

.content-wrapper {
    display: flex;
    gap: 30px;
    margin-bottom: 40px;
}

/* Bubble Chart Styles */
.chart-container {
    flex: 0 0 50%;
    background: white;
    padding: 20px;
    border-radius: 8px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
    position: relative;
}

#bubble-chart {
    width: 100%;
    height: 600px;
    display: block;
}

/* Bubble styles */
.bubble {
    stroke: #fff;
    stroke-width: 2px;
    cursor: pointer;
    transition: all 0.3s ease;
}

.bubble:hover {
    stroke-width: 3px;
    filter: brightness(1.1);
}

.bubble.selected {
    stroke: #000;
    stroke-width: 3px;
}

.bubble-label {
    font-size: 12px;
    font-weight: bold;
    pointer-events: none;
    text-anchor: middle;
    dominant-baseline: middle;
    fill: white;
    text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.5);
}

/* Tooltip Styles */
.tooltip {
    position: absolute;
    background-color: rgba(0, 0, 0, 0.8);
    color: white;
    padding: 10px 15px;
    border-radius: 5px;
    font-size: 13px;
    pointer-events: none;
    z-index: 1000;
    display: none;
    white-space: nowrap;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.2);
}

.tooltip.visible {
    display: block;
}

/* Table Styles */
.table-container {
    flex: 0 0 50%;
    background: white;
    padding: 20px;
    border-radius: 8px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
    overflow-y: auto;
    max-height: 650px;
}

#stocks-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 14px;
}

#stocks-table thead {
    background-color: #f8f9fa;
    position: sticky;
    top: 0;
    z-index: 10;
}

#stocks-table th {
    padding: 12px;
    text-align: left;
    font-weight: 600;
    border-bottom: 2px solid #dee2e6;
    color: #495057;
}

#stocks-table td {
    padding: 12px;
    border-bottom: 1px solid #dee2e6;
}

#stocks-table tbody tr {
    cursor: pointer;
    transition: background-color 0.2s ease;
}

#stocks-table tbody tr:hover {
    background-color: #f8f9fa;
}

#stocks-table tbody tr.selected {
    background-color: #e7f3ff;
    font-weight: 500;
}

/* Legend Styles */
#legend {
    background: white;
    padding: 20px;
    border-radius: 8px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

#legend h3 {
    font-size: 16px;
    margin-bottom: 15px;
    color: #444;
}

.legend-items {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 10px;
}

.legend-item {
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 13px;
}

.legend-color {
    width: 20px;
    height: 20px;
    border-radius: 50%;
    flex-shrink: 0;
}

/* Responsive Design */
@media (max-width: 1200px) {
    .content-wrapper {
        flex-direction: column;
    }

    .chart-container,
    .table-container {
        flex: 1;
    }

    #bubble-chart {
        height: 500px;
    }

    .table-container {
        max-height: 500px;
    }
}

/* Scrollbar styling */
.table-container::-webkit-scrollbar {
    width: 8px;
}

.table-container::-webkit-scrollbar-track {
    background: #f1f1f1;
    border-radius: 4px;
}

.table-container::-webkit-scrollbar-thumb {
    background: #888;
    border-radius: 4px;
}

.table-container::-webkit-scrollbar-thumb:hover {
    background: #555;
}

