    // Set up SVG
    const svg = d3.select('#bubble-chart')
        .attr('width', chartWidth)
        .attr('height', chartHeight);

    // Clear previous content
    svg.selectAll('*').remove();

    const g = svg.append('g')
        .attr('transform', `translate(${margins.left},${margins.top})`);

    // Create force simulation
    const simulation = d3.forceSimulation(validData)
        .force('x', d3.forceX(width / 2).strength(0.05))
        .force('y', d3.forceY(height / 2).strength(0.05))
        .force('collide', d3.forceCollide(d => getBubbleRadius(d.marketCap, d.sector === 'ETF') + 2))
        .stop();

    // Add sector clustering forces
    const sectorGroups = d3.group(validData, d => d.sector);
    const sectorPositions = {};
    const sectorArray = Array.from(sectorGroups.keys());

    sectorArray.forEach((sector, i) => {
        const angle = (i / sectorArray.length) * 2 * Math.PI;
        const distance = Math.min(width, height) * 0.25;
        sectorPositions[sector] = {
            x: width / 2 + distance * Math.cos(angle),
            y: height / 2 + distance * Math.sin(angle)
        };
    });

    // Update forces with sector clustering
    simulation.force('cluster-x', d3.forceX(d => sectorPositions[d.sector].x).strength(0.3))
        .force('cluster-y', d3.forceY(d => sectorPositions[d.sector].y).strength(0.3));

    // Run simulation
    for (let i = 0; i < 300; i++) {
        simulation.tick();
    }

    // Draw bubbles
    const bubbles = g.selectAll('.bubble')
        .data(validData, d => d.ticker)
        .enter()
        .append('circle')
        .attr('class', 'bubble')
        .attr('cx', d => d.x)
        .attr('cy', d => d.y)
        .attr('r', d => getBubbleRadius(d.marketCap, d.sector === 'ETF'))
        .attr('fill', d => sectorColors[d.sector] || '#999')
        .on('mouseenter', function(event, d) {
            // Show tooltip only for non-ETF stocks
            if (d.sector !== 'ETF') {
                const tooltip = document.getElementById('tooltip');
                tooltip.innerHTML = `
                    <div><strong>${d.ticker}</strong></div>
                    <div>${d['full name']}</div>
                    <div>${d.sector}</div>
                `;
                tooltip.classList.add('visible');
                tooltip.style.left = event.pageX + 10 + 'px';
                tooltip.style.top = event.pageY + 10 + 'px';
            }
        })
        .on('mousemove', function(event) {
            const tooltip = document.getElementById('tooltip');
            if (tooltip.classList.contains('visible')) {
                tooltip.style.left = event.pageX + 10 + 'px';
                tooltip.style.top = event.pageY + 10 + 'px';
            }
        })
        .on('mouseleave', function() {
            document.getElementById('tooltip').classList.remove('visible');
        })
        .on('click', function(event, d) {
            selectStock(d.ticker);
        });

    // Draw labels
    g.selectAll('.bubble-label')
        .data(validData, d => d.ticker)
        .enter()
        .append('text')
        .attr('class', 'bubble-label')
        .attr('x', d => d.x)
        .attr('y', d => d.y)
        .text(d => d.ticker);

    return { bubbles, sectorPositions };
}

// Create data table
function createTable(data) {
    const tbody = d3.select('#stocks-table tbody');

    const rows = tbody.selectAll('tr')
        .data(data, d => d.ticker)
        .enter()
        .append('tr')
        .on('click', function(event, d) {
            selectStock(d.ticker);
        });

    rows.append('td').text(d => d.ticker);
    rows.append('td').text(d => d['full name']);
    rows.append('td').text(d => d.sector);
    rows.append('td').text(d => formatMarketCap(d.marketCap));

    return rows;
}

// Create legend
function createLegend(sectorPositions) {
    const legend = d3.select('#legend');
    legend.html('<h3>Sector Legend</h3>');

    const items = legend.append('div')
        .attr('class', 'legend-items');

    Object.keys(sectorColors).forEach(sector => {
        const item = items.append('div')
            .attr('class', 'legend-item');

        item.append('div')
            .attr('class', 'legend-color')
            .style('background-color', sectorColors[sector]);

        item.append('div')
            .text(sector);
    });
}

// Select a stock - highlight in both chart and table
function selectStock(ticker) {
    selectedStock = ticker;

    // Update bubbles
    d3.selectAll('.bubble')
        .classed('selected', d => d.ticker === ticker);

    // Update table
    d3.selectAll('#stocks-table tbody tr')
        .classed('selected', (d, i) => d.ticker === ticker);

    // Scroll table to selected row if needed
    const selectedRow = document.querySelector(
        `#stocks-table tbody tr:nth-child(${currentData.findIndex(d => d.ticker === ticker) + 1})`
    );
    if (selectedRow) {
        selectedRow.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
}

// Clear selection
function clearSelection() {
    selectedStock = null;
    d3.selectAll('.bubble').classed('selected', false);
    d3.selectAll('#stocks-table tbody tr').classed('selected', false);
}

// Initialize the visualization
async function init() {
    // Load data
    const data = await loadData();

    // Filter to include only the first 50 stocks (excluding ETFs if more than 50)
    const stocks = data.filter(d => d.sector !== 'ETF').slice(0, 39);
    const etfs = data.filter(d => d.sector === 'ETF');
    currentData = [...stocks, ...etfs].slice(0, 50);

    // Add ETF sector if not present
    if (!sectorColors['ETF'] && currentData.some(d => d.sector === 'ETF')) {
        sectorColors['ETF'] = '#9467bd';
    }

    // Create bubble chart
    const { bubbles, sectorPositions } = createBubbleChart(currentData);

    // Create table
    createTable(currentData);

    // Create legend
    createLegend(sectorPositions);

    // Add event listeners for table row clicks
    d3.selectAll('#stocks-table tbody tr')
        .on('click', function(event, d) {
            selectStock(d.ticker);
        });

    // Click on body to deselect
    d3.select('body')
        .on('click', function(event) {
            if (event.target.tagName !== 'circle' &&
                event.target.tagName !== 'tr' &&
                !event.target.closest('tr')) {
                clearSelection();
            }
        });
}

// Run when document is ready
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
} else {
    init();
}
